package edu.calpoly.lambdalab.paulmotter;

import java.util.UUID;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

/**
 * A validated RobotDistanceLambda event received from csc5100/events/robot-distance.
 * Expected JSON: {"id":"&lt;uuid&gt;","operation":"RobotDistanceLambda","result":&lt;distance&gt;, ...}.
 * Additional fields are kept in {@code raw} so they can still be displayed.
 *
 * @param id correlation UUID generated by the Lambda
 * @param operation the producing Lambda name
 * @param result the calculated distance
 * @param raw the full parsed JSON
 *
 * @author Paul Motter (PaulMotter)
 * @version 1.0 (10/21/2026)
 */
record RobotDistanceEvent(String id, String operation, double result, JsonNode raw) {
    static final String OPERATION = "RobotDistanceLambda";
    private static final ObjectMapper MAPPER = new ObjectMapper();

    /**
     * Parses and validates an event payload.
     *
     * @param json the MQTT payload
     * @return the validated event
     * @throws IllegalArgumentException if the payload is not a valid RobotDistanceLambda event
     */
    static RobotDistanceEvent parse(String json) {
        if (json == null || json.isBlank()) {
            throw new IllegalArgumentException("Empty payload");
        }
        JsonNode node;
        try {
            node = MAPPER.readTree(json);
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("Malformed JSON", e);
        }
        if (node == null || !node.isObject()) {
            throw new IllegalArgumentException("Event must be a JSON object");
        }

        String id = node.path("id").asText("");
        if (!isUuid(id)) {
            throw new IllegalArgumentException("Invalid or missing id");
        }

        // EventProcessorLambda accepts "lambda" as an alias for "operation".
        String operation = node.path("operation").asText("");
        if (operation.isBlank()) operation = node.path("lambda").asText("");
        if (!OPERATION.equals(operation)) {
            throw new IllegalArgumentException("Unexpected operation: " + operation);
        }

        JsonNode resultNode = node.get("result");
        if (resultNode == null || !resultNode.isNumber()) {
            throw new IllegalArgumentException("Missing numeric result");
        }
        double result = resultNode.asDouble();
        if (!Double.isFinite(result) || result < 0) {
            throw new IllegalArgumentException("result must be a finite, non-negative distance");
        }

        return new RobotDistanceEvent(id, operation, result, node);
    }

    private static boolean isUuid(String id) {
        try {
            return UUID.fromString(id).toString().equals(id);
        } catch (IllegalArgumentException e) {
            return false;
        }
    }
}
